static int mask_pollOnValue(uint32_t addr, uint32_t mask, uint32_t value)
{
  int i = 0;
    uint32_t RegVal = 0x0;
    
    RegVal = PSU_Read(addr);
  while ((RegVal & mask) != value) {
    if (i >= PSU_MASK_POLL_TIME) {
      return PSU_INIT_TIMEOUT;
    }
    i++;
    RegVal = PSU_Read(addr);
  }
  return PSU_INIT_SUCCESS;
}

