unsigned long psu_ps_pl_isolation_removal_data(void)
{
  //level-shift for 28dr board
  PSU_Mask_Write(0xffd80318, 0xffffffff, 0x4000);
  PSU_Mask_Write(0xffd80320, 0xffffffff, 0x4000);
  return PSU_INIT_SUCCESS;
}

unsigned long psu_ps_pl_reset_config_data(void)
{
  //Number of Fabric Reset = 1
  PSU_Mask_Write(0xFF0A0504, 0xffffffff, 0x80000000); // set direction to output
  PSU_Mask_Write(0xFF0A0500, 0xffffffff, 0x80000000); //wire data
  
  return PSU_INIT_SUCCESS;
}

