{
  return PSU_INIT_SUCCESS;
}

int psu_lpd_protection(void)
{
  psu_init_xppu_aper_ram();
  return PSU_INIT_SUCCESS;
}

int psu_ddr_protection(void)
{
  psu_ddr_mpu0_data();
  psu_ddr_mpu1_data();
  psu_ddr_mpu2_data();
  psu_ddr_mpu3_data();
  psu_ddr_mpu4_data();
  psu_ddr_mpu5_data();

  return PSU_INIT_SUCCESS;
}

int psu_ocm_protection(void)
{
  psu_ocm_mpu_data();

  return PSU_INIT_SUCCESS;
}

int psu_fpd_protection(void)
{
  psu_fpd_mpu_data();

  return PSU_INIT_SUCCESS;
}

int psu_protection_lock(void)
{
  psu_protection_lock_data();

  return PSU_INIT_SUCCESS;
}

int psu_protection(void)
{
  psu_apply_master_tz();
  psu_ddr_protection();
  psu_ocm_protection();
  psu_fpd_protection();
  psu_lpd_protection();

  return PSU_INIT_SUCCESS;
}


/****************************************************************************/

int psu_init(void)
{
  int ret = PSU_INIT_SUCCESS;

  ret |= psu_mio_init_data();
  ret |= psu_peripherals_pre_init_data();
  ret |= psu_pll_init_data();
  ret |= psu_clock_init_data();
  ret |= ddr_initial();
  ret |= psu_peripherals_init_data();
  ret |= psu_peripherals_powerdwn_data();
  ret |= psu_afi_config();

  if(ret != PSU_INIT_SUCCESS)
      return ret;

  return PSU_INIT_SUCCESS;
}

